actions.script:
import org.slf4j.LoggerFactory def logger = LoggerFactory.getLogger("PlaidIntegration")
logger.info("Requesting Plaid Link Token for user: ${userId}")
// MOCK RESPONSE linkToken = "link-sandbox-mock-1234567890" expiration = "2026-12-31T23:59:59Z"
logger.info("Generated Mock Link Token: ${linkToken}")

import org.slf4j.LoggerFactory def logger = LoggerFactory.getLogger("PlaidIntegration")
logger.info("Starting Bank Feed Sync for account ${bankAccountId} from ${startDate} to ${endDate}")
// MOCK: Generate some fake transactions and "insert" them into mantle.account.method.BankAccountTrans def mockTransactions = [ [amount: new BigDecimal("-150.00"), name: "Uber Ride", date: "2026-06-18", category: ["Travel", "Taxi"]], [amount: new BigDecimal("5000.00"), name: "Client Payment - Acme Corp", date: "2026-06-18", category: ["Transfer", "Deposit"]], [amount: new BigDecimal("-12.99"), name: "AWS Cloud Subscription", date: "2026-06-17", category: ["Software", "Subscription"]] ]
logger.info("Mock Sync: Pulled ${mockTransactions.size()} transactions from Plaid API.")
syncedTransactionsCount = mockTransactions.size()
logger.info("Bank Feed Sync Complete.")
